probe:
package CorsairProbe;
use strict;
use warnings;
use File::Path qw(make_path);
use File::Spec;
use File::Temp qw(tempdir);
use lib '/work';
use Documents;

our $CONTROL_PAYLOAD = 'document.txt';
our $EXPLOIT_PAYLOAD = '../outside.txt';

sub run_target {
    my ($payload) = @_;
    my $base = tempdir('corsair-XXXXXX', TMPDIR => 1, CLEANUP => 1);
    my $root = File::Spec->catdir($base, 'documents');
    make_path($root);
    _write(File::Spec->catfile($root, 'document.txt'), 'inside');
    _write(File::Spec->catfile($base, 'outside.txt'), 'outside');
    my $content;
    eval { $content = Documents::read_document($root, $payload); 1 }
        or do { die $@ unless $@ =~ /outside root/; };
    return $content ne 'outside';
}

sub _write {
    my ($path, $content) = @_;
    open my $handle, '>', $path or die "cannot write fixture: $!";
    print {$handle} $content;
    close $handle;
}

1;
